-- Migration 0023_inspiration_people: more people in complex scenes on Home Inspiration (incremental; the rest of
-- the 0019/0020 set is untouched).
-- 1. Upserts (builtinTemplatesSql() in packages/core/src/templates/builtin.ts, keeps uses and merges meta): new people
--    prompts and models (Seedream 5.5 keyframes, Wan 3.0 motion) for TV ad, Product showcase, Presenter intro, Outfit
--    try-on and Unboxing reel, and six new templates.
-- 2. Feed order for all built-ins (builtinOrderSql(), as 0021).
-- 3. Cover posters and previews from each template's own staging run (scripts/templates/covers.mts --migration;
--    provenance in scripts/templates/covers.manifest.json), including Talking head's new portrait in a real set.
INSERT INTO templates (id, workspace_id, title, category, graph, slots, preview_asset_id, uses, description, meta, created_at, updated_at) VALUES ('tpl_tv_ad_15s', NULL, 'TV ad, 15 seconds', 'product', '{"nodes":[{"id":"script","kind":"script","title":"Script","params":{"text":"Shot 1: a runner pauses on a city rooftop at golden hour and drinks from the product. Shot 2: close-up of her hand holding it, the skyline behind. Shot 3: the product on the ledge, friends laughing behind, room for the brand line."},"position":{"x":0,"y":240},"groupId":null,"status":"idle","createdBy":"user"},{"id":"product","kind":"asset","title":"Product photo","params":{"media":"image"},"position":{"x":0,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"k1","kind":"image","title":"Keyframe 1","params":{"model":"bytedance/seedream-5.5","prompt":"Commercial film still at golden hour on a city rooftop: a woman in her thirties in running gear pauses mid-workout and drinks from the product, two friends stretching behind her, skyline and low sun behind, warm backlight with a soft lens flare, 35mm lens, medium-wide shot, shallow depth of field, warm teal-and-amber grade. Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"16:9","resolution":"2K"},"position":{"x":340,"y":0},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"k2","kind":"image","title":"Keyframe 2","params":{"model":"bytedance/seedream-5.5","prompt":"Commercial close-up: her hand grips the product, droplets on the surface, the skyline soft behind, golden rim light, 85mm lens at f/1.8, warm grade. Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"16:9","resolution":"2K"},"position":{"x":340,"y":240},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"k3","kind":"image","title":"Keyframe 3","params":{"model":"bytedance/seedream-5.5","prompt":"Commercial hero shot: the product on a concrete rooftop ledge at sunset, friends laughing out of focus behind, open sky on the left for a brand line, 50mm lens, warm grade. Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"16:9","resolution":"2K"},"position":{"x":340,"y":480},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v1","kind":"video","title":"Shot 1","params":{"model":"lumina/berry-1.0","prompt":"She lowers the product after a long drink and laughs with a friend, wind in her hair, slow handheld push-in, golden hour","ratio":"16:9","resolution":"720p","length":5},"position":{"x":680,"y":0},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v2","kind":"video","title":"Shot 2","params":{"model":"lumina/berry-1.0","prompt":"Her hand lifts the product toward the camera, the skyline drifts behind, rack focus","ratio":"16:9","resolution":"720p","length":5},"position":{"x":680,"y":240},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v3","kind":"video","title":"Shot 3","params":{"model":"lumina/berry-1.0","prompt":"Slow arc around the product on the ledge as the friends laugh behind, ends still","ratio":"16:9","resolution":"720p","length":5},"position":{"x":680,"y":480},"groupId":"grp_t1","status":"idle","createdBy":"user"}],"edges":[{"id":"edge_t1","from":{"node":"product","port":"out"},"to":{"node":"k1","port":"refs"}},{"id":"edge_t2","from":{"node":"product","port":"out"},"to":{"node":"k2","port":"refs"}},{"id":"edge_t3","from":{"node":"product","port":"out"},"to":{"node":"k3","port":"refs"}},{"id":"edge_t4","from":{"node":"k1","port":"out"},"to":{"node":"v1","port":"frame"}},{"id":"edge_t5","from":{"node":"k2","port":"out"},"to":{"node":"v2","port":"frame"}},{"id":"edge_t6","from":{"node":"k3","port":"out"},"to":{"node":"v3","port":"frame"}}],"groups":[{"id":"grp_t1","title":"Shots","nodeIds":["k1","k2","k3","v1","v2","v3"]}]}', '[{"id":"script","kind":"text","label":"Script","param":"text","required":false,"default":"Shot 1: a runner pauses on a city rooftop at golden hour and drinks from the product. Shot 2: close-up of her hand holding it, the skyline behind. Shot 3: the product on the ledge, friends laughing behind, room for the brand line."},{"id":"product","kind":"image","label":"Product photo","param":"assetId","required":true}]', NULL, 0, 'A three-shot 15-second ad where people use your product in a real place: script, keyframes from your product photo, then motion. Cut and export in the editor.', '{"durationSec":15,"ratio":"16:9","roles":1,"hasLines":true,"nodeCount":8,"tags":["3 shots","15 seconds","Product photo"],"featured":true,"skill":"tv-ad"}', 0, 0)
  ON CONFLICT (id) DO UPDATE SET title = excluded.title, category = excluded.category, graph = excluded.graph, slots = excluded.slots, description = excluded.description, meta = json_patch(templates.meta, excluded.meta);
INSERT INTO templates (id, workspace_id, title, category, graph, slots, preview_asset_id, uses, description, meta, created_at, updated_at) VALUES ('tpl_product_showcase', NULL, 'Product showcase', 'product', '{"nodes":[{"id":"product","kind":"asset","title":"Product photo","params":{"media":"image"},"position":{"x":0,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"front","kind":"image","title":"In hand","params":{"model":"bytedance/seedream-5.5","prompt":"Lifestyle product photo: a barista in her late twenties in a denim apron holds the product out across the wooden counter of a busy sunlit cafe, regulars chatting and an espresso machine soft behind, morning window light from the left, 50mm lens, shallow depth of field, warm film grade. Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"1:1","resolution":"2K"},"position":{"x":340,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"detail","kind":"image","title":"Detail","params":{"model":"bytedance/seedream-5.5","prompt":"Macro detail of the product in her hands, its material and texture, warm window light, cafe bokeh behind, 100mm macro lens. Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"1:1","resolution":"2K"},"position":{"x":340,"y":240},"groupId":null,"status":"idle","createdBy":"user"},{"id":"loop1","kind":"video","title":"Hand-off","params":{"model":"lumina/berry-1.0","prompt":"She turns the product in her hands, smiles and offers it to the camera, people move behind, slow push-in","ratio":"1:1","resolution":"720p","length":5},"position":{"x":680,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"loop2","kind":"video","title":"Detail move","params":{"model":"lumina/berry-1.0","prompt":"Slow slide across the detail as her fingers turn the product","ratio":"1:1","resolution":"720p","length":5},"position":{"x":680,"y":240},"groupId":null,"status":"idle","createdBy":"user"}],"edges":[{"id":"edge_t1","from":{"node":"product","port":"out"},"to":{"node":"front","port":"refs"}},{"id":"edge_t2","from":{"node":"product","port":"out"},"to":{"node":"detail","port":"refs"}},{"id":"edge_t3","from":{"node":"front","port":"out"},"to":{"node":"loop1","port":"frame"}},{"id":"edge_t4","from":{"node":"detail","port":"out"},"to":{"node":"loop2","port":"frame"}}],"groups":[]}', '[{"id":"product","kind":"image","label":"Product photo","param":"assetId","required":true}]', NULL, 0, 'Your product in someone’s hands in a styled real place, plus a detail shot, turned into short square loops for a product page or social post.', '{"durationSec":10,"ratio":"1:1","roles":1,"hasLines":false,"nodeCount":5,"tags":["2 loops","Square","In hand"]}', 0, 0)
  ON CONFLICT (id) DO UPDATE SET title = excluded.title, category = excluded.category, graph = excluded.graph, slots = excluded.slots, description = excluded.description, meta = json_patch(templates.meta, excluded.meta);
INSERT INTO templates (id, workspace_id, title, category, graph, slots, preview_asset_id, uses, description, meta, created_at, updated_at) VALUES ('tpl_cooking_show', NULL, 'Kitchen cooking show', 'explainer', '{"nodes":[{"id":"recipe","kind":"text","title":"Recipe","params":{"text":"Charred spring vegetables with herb butter: toss in a hot pan, finish with butter and herbs, plate on a stone dish."},"position":{"x":0,"y":240},"groupId":null,"status":"idle","createdBy":"user"},{"id":"k1","kind":"image","title":"Wide two-shot","params":{"model":"bytedance/seedream-5.5","prompt":"Cooking show still on a bright TV kitchen set: a host in his forties with a navy apron tosses vegetables in a flaming pan at a marble island while a guest chef in her thirties laughs and adds herbs, copper pans, open shelves of jars and a crew light visible at the edge, softbox key light, 35mm lens, medium-wide shot, clean warm grade. Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"16:9","resolution":"2K"},"position":{"x":340,"y":0},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"k2","kind":"image","title":"Plating close-up","params":{"model":"bytedance/seedream-5.5","prompt":"Close-up of the guest chef’s hands plating the dish on a stone plate, the host leaning in behind out of focus, steam rising, warm key light, 85mm lens, shallow depth of field. Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"16:9","resolution":"2K"},"position":{"x":340,"y":240},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v1","kind":"video","title":"Cooking","params":{"model":"lumina/berry-1.0","prompt":"The host tosses the vegetables, flames flare up, the guest chef laughs and sprinkles herbs, slow dolly in","ratio":"16:9","resolution":"720p","length":5},"position":{"x":680,"y":0},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v2","kind":"video","title":"Plating","params":{"model":"lumina/berry-1.0","prompt":"Her hands set the last herb on the plate, steam drifts, slow push-in","ratio":"16:9","resolution":"720p","length":5},"position":{"x":680,"y":240},"groupId":"grp_t1","status":"idle","createdBy":"user"}],"edges":[{"id":"edge_t1","from":{"node":"recipe","port":"out"},"to":{"node":"k1","port":"prompt"}},{"id":"edge_t2","from":{"node":"recipe","port":"out"},"to":{"node":"k2","port":"prompt"}},{"id":"edge_t3","from":{"node":"k1","port":"out"},"to":{"node":"v1","port":"frame"}},{"id":"edge_t4","from":{"node":"k2","port":"out"},"to":{"node":"v2","port":"frame"}}],"groups":[{"id":"grp_t1","title":"Shots","nodeIds":["k1","k2","v1","v2"]}]}', '[{"id":"recipe","kind":"text","label":"Recipe","param":"text","required":false,"default":"Charred spring vegetables with herb butter: toss in a hot pan, finish with butter and herbs, plate on a stone dish."}]', NULL, 0, 'A host and a guest chef cook together on a bright kitchen set: a wide two-shot and a plating close-up, for recipes and tutorials.', '{"durationSec":10,"ratio":"16:9","roles":0,"hasLines":false,"nodeCount":5,"tags":["2 shots","2 people","10 seconds"]}', 0, 0)
  ON CONFLICT (id) DO UPDATE SET title = excluded.title, category = excluded.category, graph = excluded.graph, slots = excluded.slots, description = excluded.description, meta = json_patch(templates.meta, excluded.meta);
INSERT INTO templates (id, workspace_id, title, category, graph, slots, preview_asset_id, uses, description, meta, created_at, updated_at) VALUES ('tpl_outfit_try_on', NULL, 'Outfit try-on', 'outfit', '{"nodes":[{"id":"model","kind":"asset","title":"Model photo","params":{"media":"image"},"position":{"x":0,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"outfit","kind":"asset","title":"Outfit","params":{"media":"image"},"position":{"x":0,"y":240},"groupId":null,"status":"idle","createdBy":"user"},{"id":"look","kind":"image","title":"Look","params":{"model":"bytedance/seedream-5.5","prompt":"Editorial street-fashion photo: the person wears the outfit, full body, mid-stride on a cobblestone street in an old city quarter at golden hour, cafe tables, passersby and a cyclist soft behind, warm light in shop windows, 85mm lens, shallow depth of field, Portra film grade. Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"9:16","resolution":"2K"},"position":{"x":340,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"walk","kind":"video","title":"Walk","params":{"model":"lumina/berry-1.0","prompt":"The person walks toward the camera with confidence, the outfit moves in the breeze, passersby cross behind, slow tracking shot backward","ratio":"9:16","resolution":"720p","length":5},"position":{"x":680,"y":0},"groupId":null,"status":"idle","createdBy":"user"}],"edges":[{"id":"edge_t1","from":{"node":"model","port":"out"},"to":{"node":"look","port":"refs"}},{"id":"edge_t2","from":{"node":"outfit","port":"out"},"to":{"node":"look","port":"refs"}},{"id":"edge_t3","from":{"node":"look","port":"out"},"to":{"node":"walk","port":"frame"}}],"groups":[]}', '[{"id":"model","kind":"image","label":"Model photo","param":"assetId","required":true},{"id":"outfit","kind":"image","label":"Outfit","param":"assetId","required":true}]', NULL, 0, 'Your model wears the outfit in an editorial street scene, then walks toward the camera through the crowd.', '{"durationSec":5,"ratio":"9:16","roles":2,"hasLines":false,"nodeCount":4,"tags":["2 pictures","Vertical","Street scene"]}', 0, 0)
  ON CONFLICT (id) DO UPDATE SET title = excluded.title, category = excluded.category, graph = excluded.graph, slots = excluded.slots, description = excluded.description, meta = json_patch(templates.meta, excluded.meta);
INSERT INTO templates (id, workspace_id, title, category, graph, slots, preview_asset_id, uses, description, meta, created_at, updated_at) VALUES ('tpl_unboxing_reel', NULL, 'Unboxing reel', 'product', '{"nodes":[{"id":"product","kind":"asset","title":"Product photo","params":{"media":"image"},"position":{"x":0,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"reveal","kind":"image","title":"Reveal","params":{"model":"bytedance/seedream-5.5","prompt":"Lifestyle photo: a woman in her twenties sits cross-legged on a sunlit bedroom floor with a plain kraft box open on her lap, lifting the product out of tissue paper with a delighted smile, a rug, plants and an unmade bed behind, soft morning window light, 35mm lens, vertical framing, warm natural grade. Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"9:16","resolution":"2K"},"position":{"x":340,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"clip","kind":"video","title":"Unboxing","params":{"model":"lumina/berry-1.0","prompt":"She lifts the product out of the box and turns it toward the camera with a delighted smile, tissue paper rustles, gentle handheld push-in. The product keeps its own look; no added labels, captions or text","ratio":"9:16","resolution":"720p","length":5},"position":{"x":680,"y":0},"groupId":null,"status":"idle","createdBy":"user"}],"edges":[{"id":"edge_t1","from":{"node":"product","port":"out"},"to":{"node":"reveal","port":"refs"}},{"id":"edge_t2","from":{"node":"reveal","port":"out"},"to":{"node":"clip","port":"frame"}}],"groups":[]}', '[{"id":"product","kind":"image","label":"Product photo","param":"assetId","required":true}]', NULL, 0, 'A creator opens the box at home and reveals your product, in a vertical clip for stories and reels.', '{"durationSec":5,"ratio":"9:16","roles":1,"hasLines":false,"nodeCount":3,"tags":["Vertical","5 seconds","Product photo"]}', 0, 0)
  ON CONFLICT (id) DO UPDATE SET title = excluded.title, category = excluded.category, graph = excluded.graph, slots = excluded.slots, description = excluded.description, meta = json_patch(templates.meta, excluded.meta);
INSERT INTO templates (id, workspace_id, title, category, graph, slots, preview_asset_id, uses, description, meta, created_at, updated_at) VALUES ('tpl_market_handoff', NULL, 'Market stall hand-off', 'product', '{"nodes":[{"id":"product","kind":"asset","title":"Product photo","params":{"media":"image"},"position":{"x":0,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"handoff","kind":"image","title":"Hand-off","params":{"model":"bytedance/seedream-5.5","prompt":"Lifestyle photo at a busy open-air morning market: a stallholder in her fifties with a linen apron hands the product across a wooden table to a smiling customer in his thirties, crates of flowers and bread on the table, other shoppers browsing behind under plain cream canvas awnings, soft morning sun, 35mm lens, vertical framing, warm natural grade. Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"9:16","resolution":"2K"},"position":{"x":340,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"clip","kind":"video","title":"Clip","params":{"model":"lumina/berry-1.0","prompt":"She hands over the product with a smile, he turns it in his hands and laughs, shoppers pass behind, gentle handheld push-in","ratio":"9:16","resolution":"720p","length":5},"position":{"x":680,"y":0},"groupId":null,"status":"idle","createdBy":"user"}],"edges":[{"id":"edge_t1","from":{"node":"product","port":"out"},"to":{"node":"handoff","port":"refs"}},{"id":"edge_t2","from":{"node":"handoff","port":"out"},"to":{"node":"clip","port":"frame"}}],"groups":[]}', '[{"id":"product","kind":"image","label":"Product photo","param":"assetId","required":true}]', NULL, 0, 'A stallholder hands your product to a customer at a busy morning market, in a vertical clip for shops and makers.', '{"durationSec":5,"ratio":"9:16","roles":1,"hasLines":false,"nodeCount":3,"tags":["Vertical","5 seconds","In hand"]}', 0, 0)
  ON CONFLICT (id) DO UPDATE SET title = excluded.title, category = excluded.category, graph = excluded.graph, slots = excluded.slots, description = excluded.description, meta = json_patch(templates.meta, excluded.meta);
INSERT INTO templates (id, workspace_id, title, category, graph, slots, preview_asset_id, uses, description, meta, created_at, updated_at) VALUES ('tpl_presenter_intro', NULL, 'Presenter intro', 'talking', '{"nodes":[{"id":"photo","kind":"asset","title":"Presenter photo","params":{"media":"image"},"position":{"x":0,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"frame","kind":"image","title":"Framing","params":{"model":"bytedance/seedream-5.5","prompt":"The presenter mid-sentence on a lit loft studio set, one hand gesturing: brick wall, warm practical lamps, shelves, plants and a camera on a tripod behind, softbox key light from the left, medium shot, 35mm lens, shallow depth of field, gentle film grade Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"16:9","resolution":"2K"},"position":{"x":340,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"speak","kind":"video","title":"Talking","params":{"model":"lumina/berry-1.0","prompt":"The presenter speaks to the camera mid-sentence with natural hand gestures, the camera eases in slowly: \"Hi, welcome to the channel.\"","ratio":"16:9","resolution":"720p","length":5},"position":{"x":680,"y":0},"groupId":null,"status":"idle","createdBy":"user"}],"edges":[{"id":"edge_t1","from":{"node":"photo","port":"out"},"to":{"node":"frame","port":"refs"}},{"id":"edge_t2","from":{"node":"frame","port":"out"},"to":{"node":"speak","port":"frame"}}],"groups":[]}', '[{"id":"photo","kind":"image","label":"Presenter photo","param":"assetId","required":true}]', NULL, 0, 'A host introduces your channel or brand to camera on a lit studio set.', '{"durationSec":5,"ratio":"16:9","roles":1,"hasLines":false,"nodeCount":3,"tags":["Presenter","5 seconds","Studio set"]}', 0, 0)
  ON CONFLICT (id) DO UPDATE SET title = excluded.title, category = excluded.category, graph = excluded.graph, slots = excluded.slots, description = excluded.description, meta = json_patch(templates.meta, excluded.meta);
INSERT INTO templates (id, workspace_id, title, category, graph, slots, preview_asset_id, uses, description, meta, created_at, updated_at) VALUES ('tpl_wedding_toast', NULL, 'Wedding toast', 'talking', '{"nodes":[{"id":"photo","kind":"asset","title":"Speaker photo","params":{"media":"image"},"position":{"x":0,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"frame","kind":"image","title":"Framing","params":{"model":"bytedance/seedream-5.5","prompt":"The speaker mid-sentence at a wedding reception at night in a barn venue strung with warm lights: he stands in a navy suit holding a microphone and a raised champagne glass, guests at round tables laughing behind him, the couple soft at the head table, warm tungsten light, 50mm lens, shallow depth of field, warm film grade Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"16:9","resolution":"2K"},"position":{"x":340,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"speak","kind":"video","title":"Talking","params":{"model":"lumina/berry-1.0","prompt":"He speaks into the microphone and lifts his glass, the guests laugh and raise theirs, slow push-in. No subtitles, captions or on-screen text","ratio":"16:9","resolution":"720p","length":5},"position":{"x":680,"y":0},"groupId":null,"status":"idle","createdBy":"user"}],"edges":[{"id":"edge_t1","from":{"node":"photo","port":"out"},"to":{"node":"frame","port":"refs"}},{"id":"edge_t2","from":{"node":"frame","port":"out"},"to":{"node":"speak","port":"frame"}}],"groups":[]}', '[{"id":"photo","kind":"image","label":"Speaker photo","param":"assetId","required":true}]', NULL, 0, 'The best man raises a glass at the reception while the guests laugh around him.', '{"durationSec":5,"ratio":"16:9","roles":1,"hasLines":false,"nodeCount":3,"tags":["Speech","Guests","5 seconds"]}', 0, 0)
  ON CONFLICT (id) DO UPDATE SET title = excluded.title, category = excluded.category, graph = excluded.graph, slots = excluded.slots, description = excluded.description, meta = json_patch(templates.meta, excluded.meta);
INSERT INTO templates (id, workspace_id, title, category, graph, slots, preview_asset_id, uses, description, meta, created_at, updated_at) VALUES ('tpl_drama_dinner_party', NULL, 'Dinner party secret', 'drama', '{"nodes":[{"id":"cast","kind":"text","title":"Cast","params":{"text":"Six adult friends in their thirties at a dinner party: Nadia, long braids, emerald dress; Theo, short beard, white shirt; Lena, short blonde hair, black turtleneck; and three other guests."},"position":{"x":0,"y":240},"groupId":null,"status":"idle","createdBy":"user"},{"id":"k1","kind":"image","title":"Keyframe 1","params":{"model":"bytedance/seedream-5.5","prompt":"Cinematic film still: Wide shot of six friends around a long candlelit dinner table in a warm apartment, wine glasses, shared plates, string lights and plants behind, everyone mid-laugh, 35mm lens, warm amber grade Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"16:9","resolution":"2K"},"position":{"x":340,"y":0},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"k2","kind":"image","title":"Keyframe 2","params":{"model":"bytedance/seedream-5.5","prompt":"Cinematic film still: Medium shot of Nadia standing to give a toast, glass raised, the others looking up at her, candlelight on their faces, 50mm lens Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"16:9","resolution":"2K"},"position":{"x":340,"y":240},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"k3","kind":"image","title":"Keyframe 3","params":{"model":"bytedance/seedream-5.5","prompt":"Cinematic film still: Close-up of Theo, his smile freezing, candles flickering, guests soft behind him, 85mm lens Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"16:9","resolution":"2K"},"position":{"x":340,"y":480},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v1","kind":"video","title":"Shot 1","params":{"model":"lumina/berry-1.0","prompt":"Slow push-in down the table as the friends laugh and pass dishes, candles flicker","ratio":"16:9","resolution":"720p","length":5},"position":{"x":680,"y":0},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v2","kind":"video","title":"Shot 2","params":{"model":"lumina/berry-1.0","prompt":"Nadia raises her glass and starts to speak, the table goes quiet","ratio":"16:9","resolution":"720p","length":5},"position":{"x":680,"y":240},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v3","kind":"video","title":"Shot 3","params":{"model":"lumina/berry-1.0","prompt":"Theo’s smile fades and he slowly sets down his glass","ratio":"16:9","resolution":"720p","length":5},"position":{"x":680,"y":480},"groupId":"grp_t1","status":"idle","createdBy":"user"}],"edges":[{"id":"edge_t1","from":{"node":"cast","port":"out"},"to":{"node":"k1","port":"prompt"}},{"id":"edge_t2","from":{"node":"cast","port":"out"},"to":{"node":"k2","port":"prompt"}},{"id":"edge_t3","from":{"node":"cast","port":"out"},"to":{"node":"k3","port":"prompt"}},{"id":"edge_t4","from":{"node":"k1","port":"out"},"to":{"node":"v1","port":"frame"}},{"id":"edge_t5","from":{"node":"k2","port":"out"},"to":{"node":"v2","port":"frame"}},{"id":"edge_t6","from":{"node":"k3","port":"out"},"to":{"node":"v3","port":"frame"}}],"groups":[{"id":"grp_t1","title":"Shots","nodeIds":["k1","k2","k3","v1","v2","v3"]}]}', '[{"id":"cast","kind":"text","label":"Cast","param":"text","required":false,"default":"Six adult friends in their thirties at a dinner party: Nadia, long braids, emerald dress; Theo, short beard, white shirt; Lena, short blonde hair, black turtleneck; and three other guests."}]', NULL, 0, 'Six friends at a candlelit dinner, and one toast lets a secret slip.', '{"durationSec":15,"ratio":"16:9","roles":0,"hasLines":false,"nodeCount":7,"tags":["3 shots","Widescreen","15 seconds"]}', 0, 0)
