INSERT INTO templates (id, workspace_id, title, category, graph, slots, preview_asset_id, uses, description, meta, created_at, updated_at) VALUES ('tpl_drama_last_rehearsal', NULL, 'Last rehearsal', 'drama', '{"nodes":[{"id":"cast","kind":"text","title":"Cast","params":{"text":"Five adult dancers in their twenties in plain rehearsal clothes; the lead pair: Ines, tall, dark hair in a bun, grey leotard; Jonah, shaved head, loose white tee."},"position":{"x":0,"y":240},"groupId":null,"status":"idle","createdBy":"user"},{"id":"k1","kind":"image","title":"Keyframe 1","params":{"model":"bytedance/seedream-5.5","prompt":"Cinematic film still: Upright vertical frame, camera level with the floor: wide shot of five dancers standing mid-routine in a sunlit rehearsal studio with a wooden floor and tall windows, dust in the light beams, the choreographer watching from a chair with crossed arms, 24mm lens, warm natural grade Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"9:16","resolution":"2K"},"position":{"x":340,"y":0},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"k2","kind":"image","title":"Keyframe 2","params":{"model":"bytedance/seedream-5.5","prompt":"Cinematic film still: Medium shot of Jonah lifting Ines overhead, both straining, the others watching and holding their breath, 35mm lens Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"9:16","resolution":"2K"},"position":{"x":340,"y":240},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"k3","kind":"image","title":"Keyframe 3","params":{"model":"bytedance/seedream-5.5","prompt":"Cinematic film still: Close-up of the choreographer finally smiling, sunlight on her face, 85mm lens Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"9:16","resolution":"2K"},"position":{"x":340,"y":480},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v1","kind":"video","title":"Shot 1","params":{"model":"lumina/berry-1.0","prompt":"The dancers move in sync across the floor, the camera glides alongside","ratio":"9:16","resolution":"720p","length":5},"position":{"x":680,"y":0},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v2","kind":"video","title":"Shot 2","params":{"model":"lumina/berry-1.0","prompt":"Jonah lifts Ines and she holds the pose, the others start to cheer","ratio":"9:16","resolution":"720p","length":5},"position":{"x":680,"y":240},"groupId":"grp_t1","status":"idle","createdBy":"user"},{"id":"v3","kind":"video","title":"Shot 3","params":{"model":"lumina/berry-1.0","prompt":"She smiles and starts clapping slowly","ratio":"9:16","resolution":"720p","length":5},"position":{"x":680,"y":480},"groupId":"grp_t1","status":"idle","createdBy":"user"}],"edges":[{"id":"edge_t1","from":{"node":"cast","port":"out"},"to":{"node":"k1","port":"prompt"}},{"id":"edge_t2","from":{"node":"cast","port":"out"},"to":{"node":"k2","port":"prompt"}},{"id":"edge_t3","from":{"node":"cast","port":"out"},"to":{"node":"k3","port":"prompt"}},{"id":"edge_t4","from":{"node":"k1","port":"out"},"to":{"node":"v1","port":"frame"}},{"id":"edge_t5","from":{"node":"k2","port":"out"},"to":{"node":"v2","port":"frame"}},{"id":"edge_t6","from":{"node":"k3","port":"out"},"to":{"node":"v3","port":"frame"}}],"groups":[{"id":"grp_t1","title":"Shots","nodeIds":["k1","k2","k3","v1","v2","v3"]}]}', '[{"id":"cast","kind":"text","label":"Cast","param":"text","required":false,"default":"Five adult dancers in their twenties in plain rehearsal clothes; the lead pair: Ines, tall, dark hair in a bun, grey leotard; Jonah, shaved head, loose white tee."}]', NULL, 0, 'A dance crew’s final run-through before opening night, and the lift that has never worked.', '{"durationSec":15,"ratio":"9:16","roles":0,"hasLines":false,"nodeCount":7,"tags":["3 shots","Vertical","15 seconds"]}', 0, 0)
