INSERT INTO templates (id, workspace_id, title, category, graph, slots, preview_asset_id, uses, description, meta, created_at, updated_at) VALUES ('tpl_concert_vlog', NULL, 'Concert crowd vlog', 'venue', '{"nodes":[{"id":"crowd","kind":"image","title":"In the crowd","params":{"model":"bytedance/seedream-5.5","prompt":"Vertical selfie-vlog frame seen from the front camera at arm’s length, no phone visible in the frame, at a packed outdoor concert at night: a woman in her twenties laughs into the lens, two friends beside her singing along, a crowd with raised hands behind, stage lights cutting through haze, confetti in the air, 24mm wide lens, saturated stage-light grade. Fictional adults only, no real people. No logos, no brand marks, no readable text.","ratio":"9:16","resolution":"2K"},"position":{"x":340,"y":0},"groupId":null,"status":"idle","createdBy":"user"},{"id":"clip","kind":"video","title":"Vlog","params":{"model":"lumina/berry-1.0","prompt":"The friends jump and sing along, confetti falls, stage lights sweep through the haze, handheld selfie movement","ratio":"9:16","resolution":"720p","length":5},"position":{"x":680,"y":0},"groupId":null,"status":"idle","createdBy":"user"}],"edges":[{"id":"edge_t1","from":{"node":"crowd","port":"out"},"to":{"node":"clip","port":"frame"}}],"groups":[]}', '[]', NULL, 0, 'Friends film themselves in the crowd as the stage lights hit, for venue, festival and event promos.', '{"durationSec":5,"ratio":"9:16","roles":0,"hasLines":false,"nodeCount":2,"tags":["Vertical","5 seconds","Crowd"]}', 0, 0)
